mapper.select:
SELECT COUNT(1)
FROM tenant
WHERE id = #{tenantId}

SELECT COUNT(1)
FROM tenant
WHERE code = #{code}

mapper.update:
UPDATE tenant
SET status      = #{status},
    update_time = #{updateTime},
    update_user = #{updateUser}
WHERE id = #{tenantId}

UPDATE tenant
SET org_id      = #{orgId},
    update_time = #{updateTime},
    update_user = #{updateUser}
WHERE id = #{tenantId}

UPDATE tenant
SET name        = #{name},
    update_time = #{updateTime},
    update_user = #{updateUser}
WHERE id = #{tenantId}

UPDATE tenant
SET active_db_role = #{activeDbRole},
    update_time = #{updateTime},
    update_user = #{updateUser}
WHERE id = #{tenantId}

UPDATE tenant
SET shadow_maintenance_state = #{maintenanceState},
    shadow_maintenance_until = #{maintenanceUntil},
    update_time = #{updateTime},
    update_user = #{updateUser}
WHERE id = #{tenantId}

UPDATE tenant
SET shadow_maintenance_state = NULL,
    shadow_maintenance_until = NULL,
    update_time = #{updateTime},
    update_user = #{updateUser}
WHERE id = #{tenantId}
